  if(TRACK_B_IMPLEMENTATION_MODE==='ACTIVE'){
    const cohorts=new Map();let order=0;
    for(const q of o.offboard.queue){
      if(!o.offboard.sources.get(q.sourceId)?.connected)continue;
      if(q.availableAtS>now){pending.push(q);continue;}
      if(now-q.measuredAtS>OBSERVER_POLICY_C.externalMaxAgeS){o.offboard.rejected++;continue;}
